// NASA / GE E3 风扇组件。参考比例 1:10，单位 mm，X 为轴向，+X 朝进气端。
// 叶片由本文件的归一化截面数据、参数变换和闭合样条放样构造；无模型导入。
// 叶型：20150003286_data.zip / LPC/fan.igs（离线测量截面，运行时重建平滑实体）。
// 轮毂与中部凸台：同包 LPC/hub.igs、part_span_shroud_upper/lower.igs。
// 根部连接：NASA-CR-165148 图 47、51；无尺寸处为明确标识的教学重建，非制造图。
const METAL = '#b9c7d3', DISK = '#647987', EDGE = '#dce5eb';
const SPRING = '#cc9254', DARK = '#263946', BASE = '#172631';
const BLADE_COUNT = 32, PITCH = 360 / BLADE_COUNT, ROOT_GAP = 0.25;
const HUB_PROFILE = [[-15,50.220516],[-14,49.927383],[-13,49.612083],[-12,49.268889],[-11,48.890962],[-10,48.465819],[-9,47.971018],[-8,47.383687],[-7,46.72811],[-6,46.050714],[-5,45.379343],[-4,44.716109],[-3,44.06889],[-2,43.442519],[-1,42.828595],[0,42.216725],[1,41.609217],[2,41.008446],[3,40.416667],[4,39.831011],[5,39.239354],[6,38.632996],[7,38.02779],[8,37.432822],[9,36.832416],[10,36.205793],[11,35.570419],[12,34.935268],[13,34.300158],[14,33.66532],[15,33.030696]];

function polygon(d, points) {
    d.start_sketch('profile','z');
    for(let i=0;i<points.length;i++)d.line_segment(...points[i],...points[(i+1)%points.length]);
    d.end_sketch();
}
function box(x,y,z,color,radius=0) {
    const d=new PartCode3dDocument();d.box('union',x,y,z,color);
    if(radius>0)d.fillet(radius,'xyz');return d;
}
// Profile tuples are [radius, axial X]; the solid's axis is X.
function turn(profile,color) {
    const d=new PartCode3dDocument();
    polygon(d,profile.map(p=>[p[0],p[1],0]));
    d.revolve('union',360,'y',color,true);d.rotate('z',-90);return d;
}
function ring(ro,ri,length,color) {
    return turn([[ri,-length/2],[ro,-length/2],[ro,length/2],[ri,length/2]],color);
}
// Cross-section [tangential Z, radial Y], extruded along X and centred.
function axialPrism(points,length,color) {
    const d=new PartCode3dDocument();
    polygon(d,points.map(p=>[-p[0],p[1],0]));d.extrude('union',length,color,true);
    d.rotate('y',90);d.translate(-length/2,0,0);return d;
}
function sectorMask(halfAngle, radius=140, length=100) {
    const p=[[0,0]];
    for(let i=0;i<=32;i++) {
        const a=(-halfAngle+2*halfAngle*i/32)*Math.PI/180;
        p.push([radius*Math.sin(a),radius*Math.cos(a)]);
    }
    return axialPrism(p,length,DISK);
}
function hubSolid(extra=0) {
    const p=[[0,-15],...HUB_PROFILE.map(([x,r])=>[r+extra,x]),[0,15]];
    return turn(p,METAL);
}

function bladeDesign(params={}) {
    const design={chordScale:params?.chordScale??1,thicknessScale:params?.thicknessScale??1,tipTwist:params?.tipTwist??0};
    for(const [name,lo,hi] of [['chordScale',.9,1.1],['thicknessScale',.8,1.2],['tipTwist',-5,5]]) {
        const value=design[name];
        if(typeof value!=='number'||!Number.isFinite(value)||value<lo||value>hi)
            throw new Error(name+' must be a finite number in ['+lo+', '+hi+']');
    }
    return design;
}
function airfoilSections(params={}) {
    const {chordScale,thicknessScale,tipTwist}=bladeDesign(params);
    return FAN_SECTIONS.map(section=>{
        // Keep the root attachment unchanged; blend the design change above the platform.
        const t=Math.max(0,Math.min(1,(section.radius-51)/(105.41-51)));
        const blend=t*t*(3-2*t), chord=section.chord*(1+(chordScale-1)*blend);
        const thick=1+(thicknessScale-1)*blend;
        const a=section.angle*Math.PI/180,turn=tipTwist*blend*Math.PI/180;
        const c=Math.cos(a),s=Math.sin(a),ct=Math.cos(turn),st=Math.sin(turn);
        // Change chord / twist about the quarter-chord, leaving the stacking reference explicit.
        const cx=section.leading[0]+section.chord*.25*c,cz=section.leading[1]+section.chord*.25*s;
        return section.profile.flatMap(([u,ordinate,camber])=>{
            const x=(u-.25)*chord,z=(camber+(ordinate-camber)*thick)*chord;
            const dx=x*c-z*s,dz=x*s+z*c;
            return [cx+dx*ct-dz*st,section.radius,cz+dx*st+dz*ct];
        });
    });
}
function airfoilSolid(params={}) {
    const sections=airfoilSections(params);
    if(typeof parapoly_engine?.ParaPolyShapeMaker?.spline_loft!=='function')
        throw new Error('This example needs an engine build with spline_loft support.');
    const shape=parapoly_engine.ParaPolyShapeMaker.spline_loft(sections);
    const d=new PartCode3dDocument();
    d.push_node('union','section-loft-airfoil',METAL,false).set_topo_shape(shape);
    d.pop_node();return d;
}

function trimmedAirfoil(params={}) {
    const d=new PartCode3dDocument();d.push_node('union','NASA-airfoil-trim',METAL,true);
    d.add_part(airfoilSolid(params),'union','code-built-airfoil',METAL);
    // Remove the portion below the documented axisymmetric gas-path boundary.
    d.add_part(hubSolid(0),'difference','hub-flowpath-cutter');d.pop_node();return d;
}
function platform() {
    const d=new PartCode3dDocument();d.push_node('union','curved-platform',METAL,true);
    const p=HUB_PROFILE.filter(([x])=>x>=-10&&x<=10);
    d.add_part(turn([...p.map(([x,r])=>[r,x]),...p.slice().reverse().map(([x,r])=>[r-1.2,x])],METAL),'union','annular-platform');
    d.add_part(sectorMask(PITCH/2-.08),'intersection','platform-pitch');d.pop_node();return d;
}
function rootBody() {
    const d=new PartCode3dDocument();d.push_node('union','blade-root-and-shank',METAL,true);
    // The flared dovetail, drop-down space, pins and spring follow Fig. 47 / 51.
    // The dimensions and 0.25 mm model clearance are inferred, not GE tolerances.
    const root=axialPrism([[-1.10,35.8],[-1.10,33],[-2.30,30],[-2.30,28.5],[2.30,28.5],[2.30,30],[1.10,33],[1.10,35.8]],22,METAL);
    d.add_part(root,'union','ten-degree-dovetail');d.rotate('y',10);
    const shank=box(19.5,20,2.1,METAL);d.add_part(shank,'union','shank');d.rotate('y',10);d.translate(0,42,0);
    d.add_part(hubSolid(-.75),'intersection','shank-follows-hub');
    d.pop_node();return d;
}
function midspanShroud() {
    const d=new PartCode3dDocument();d.push_node('union','NASA-part-span-shroud',METAL,true);
    d.add_part(turn(SHROUD_PROFILE,METAL),'union','shroud-flowpath');
    d.add_part(sectorMask(PITCH/2-.06),'intersection','interlocking-sector');d.pop_node();return d;
}
function blade(airfoil,root,foot,shroud) {
    const d=new PartCode3dDocument();d.push_node('union','GE-E3-blade',METAL,true);
    d.add_part(airfoil,'union','NASA-airfoil',METAL);
    d.add_part(foot,'union','blade-platform',METAL);
    d.add_part(root,'union','blade-dovetail',METAL);
    d.add_part(shroud,'union','blade-shroud',METAL);
    d.pop_node();return d;
}
function wheel(detail) {
    const d=new PartCode3dDocument();d.push_node('union','slotted-disk',DISK,true);
    d.add_part(ring(34.4,11.5,24,DISK),'union','disk-rim');
    const slot=axialPrism([[-1.35,36],[-1.35,33],[-2.55,30],[-2.55,26.2],[2.55,26.2],[2.55,30],[1.35,33],[1.35,36]],30,DISK);
    const inclined=new PartCode3dDocument();inclined.add_part(slot,'union','slot-inclination');inclined.rotate('y',10);
    for(let i=0;i<BLADE_COUNT;i++) {d.add_part(inclined,'difference','slot-'+i);d.rotate('x',i*PITCH);}
    const holes=new PartCode3dDocument();holes.push_node('union','paired-pin-sockets',DISK,true);
    for(const side of [-1,1]) {holes.cylinder('union',.78,6.8,DISK);holes.translate(11,29.2,side*3.1);}
    holes.pop_node();
    const pinSockets=new PartCode3dDocument();pinSockets.add_part(holes,'union','pin-sockets');pinSockets.rotate('y',10);
    for(let i=0;i<BLADE_COUNT;i++) {d.add_part(pinSockets,'difference','pin-sockets-'+i);d.rotate('x',i*PITCH);}
    for(let i=0;i<16;i++) {
        const a=(i*22.5+5.625)*Math.PI/180;
        d.add_part(ring(1.3,0,30,DISK),'difference','flange-hole-'+i);
        d.translate(0,20.5*Math.cos(a),20.5*Math.sin(a));
    }
    if(detail)d.add_part(sectorMask(2.5*PITCH),'intersection','disk-section');
    d.pop_node();return d;
}
function antiClankSpring() {
    const d=new PartCode3dDocument();d.push_node('union','anticlank-spring',SPRING,true);
    // Stepped leaf spring, open under the dovetail, with front locking tab.
    polygon(d,[[-13,0,0],[-12,.6,0],[-7,.6,0],[-5,1.05,0],[5,1.05,0],[7,.6,0],[10.5,.6,0],[10.5,0,0],[6.5,0,0],[4.5,.45,0],[-4.5,.45,0],[-6.5,0,0]]);
    d.extrude('union',3.7,SPRING,true);d.translate(0,26.5,-1.85);
    d.add_part(box(4.8,.65,4.4,SPRING),'union','front-tab');d.translate(12,26.825,0);
    d.cylinder('difference',.75,4,SPRING);d.translate(12.5,26.8,0);
    d.pop_node();return d;
}
function lockingKey() {
    const d=new PartCode3dDocument();d.push_node('union','locking-key',EDGE,true);
    d.add_part(box(7,.7,3.6,EDGE),'union','key-tab');d.translate(11,27.7,0);
    d.add_part(box(2.4,1.2,4.7,EDGE),'union','key-head');d.translate(7.5,28,0);
    d.cylinder('difference',.65,4,EDGE);d.translate(12.5,27.7,0);
    d.pop_node();return d;
}
function retainerPin() {
    const d=new PartCode3dDocument();d.push_node('union','notched-retainer-pin',EDGE,true);
    d.cylinder('union',.72,6.3,EDGE);
    d.box('difference',2,1.15,1.8,EDGE);d.translate(.9,-1.5,0);
    d.pop_node();return d;
}
function screw() {
    const d=new PartCode3dDocument();d.push_node('union','locking-bolt',DARK,true);
    d.cylinder('union',.60,3.3,DARK);
    d.prism('union',6,1.15,.9,DARK);d.translate(0,-1.9,0);
    d.cylinder('difference',.45,.5,DARK);d.translate(0,-2.3,0);
    d.pop_node();return d;
}

let main=function(params) {
    const view=params?.view??'assembly', angle=params?.rotorAngle??0;
    const scale=params?.scale??1, explode=params?.explode??true;
    if(!['assembly','detail','attachment','blade'].includes(view))throw new Error('view 必须是 assembly、detail、attachment 或 blade');
    if(typeof angle!=='number'||!Number.isFinite(angle))throw new Error('rotorAngle 必须是有限数');
    if(typeof scale!=='number'||!Number.isFinite(scale)||scale<.5||scale>5)throw new Error('scale 必须是 0.5 到 5 的有限数');
    if(typeof explode!=='boolean')throw new Error('explode 必须是布尔值');
    bladeDesign(params);
    const d=new PartCode3dDocument(), detail=view==='detail'||view==='attachment';
    const air=trimmedAirfoil(params), foot=platform(), root=rootBody(), shroud=midspanShroud();
    let vane=blade(air,root,foot,shroud);
    if(view==='attachment') {
        const section=new PartCode3dDocument();section.push_node('union','blade-root-section',METAL,true);
        section.add_part(vane,'union','blade');section.box('intersection',100,52,100,METAL);section.translate(0,26,0);
        section.pop_node();vane=section;
    }
    if(view==='blade') {d.add_part(vane,'union','single-blade');d.scale(scale,scale,scale);return d;}
    const centerY=detail?0:116;
    const assembly=new PartCode3dDocument();
    assembly.add_part(wheel(detail),'union','32-slot-disk',DISK);
    const spring=antiClankSpring(),key=lockingKey(),pin=retainerPin(),bolt=screw();
    function place(part,name,a,x=0,y=0,z=0,yaw=0) {
        const group=new PartCode3dDocument();group.add_part(part,'union',name);group.translate(x,y,z);
        const oriented=new PartCode3dDocument();oriented.add_part(group,'union',name+'-inclination');oriented.rotate('y',yaw);
        assembly.add_part(oriented,'union',name+'-placement');assembly.rotate('x',a);
    }
    const indices=detail?[-1,0,1]:Array.from({length:BLADE_COUNT},(_,i)=>i);
    for(const i of indices) {
        const a=i*PITCH, opened=detail&&explode&&i===0, shift=opened?31:0;
        // Withdrawal is axial. Radial pull would not clear a dovetail.
        place(vane,'fan-blade-'+i,a,shift,0,0);
        place(spring,'spring-'+i,a,opened?30:0,opened?-9:0,0,10);
        place(key,'key-'+i,a,opened?36:0,opened?-4:0,0,10);
        for(const side of [-1,1])place(pin,'retainer-'+i+'-'+side,a,opened?26:11,opened?18:29.2,side*3.1,10);
        place(bolt,'bolt-'+i,a,opened?48:12.5,opened?10:26.5,0,10);
    }
    if(!detail) {
        assembly.add_part(ring(24,11.5,4,DISK),'union','front-attachment-flange');assembly.translate(14.1,0,0);
        assembly.add_part(ring(18,11.5,11,DARK),'union','rear-shaft-hub');assembly.translate(-17.5,0,0);
        assembly.add_part(ring(11.35,7.8,45,EDGE),'union','hollow-shaft');assembly.translate(-10,0,0);
        for(let i=0;i<16;i++) {
            const a=(i*22.5+5.625)*Math.PI/180;
            assembly.add_part(ring(2,1.2,.6,EDGE),'union','flange-washer-'+i);
            assembly.translate(16.4,20.5*Math.cos(a),20.5*Math.sin(a));
        }
        // Open centre intentionally exposes the shaft, flange and individual retainers.
    }
    const rotating=new PartCode3dDocument();rotating.add_part(assembly,'union','fan-module');rotating.rotate('x',angle);
    d.add_part(rotating,'union','reference-assembly');d.translate(0,centerY,0);
    if(!detail) {
        d.add_part(box(70,8,126,BASE,2),'union','display-plinth');d.translate(-13,4,0);
        d.add_part(box(14,91,16,DARK,1.2),'union','rear-pedestal');d.translate(-25,53.5,0);
        d.add_part(ring(19.5,18.2,8,DISK),'union','shaft-cradle');d.translate(-20,116,0);
    }
    const result=new PartCode3dDocument();result.add_part(d,'union','GE-E3-fan-reference');result.scale(scale,scale,scale);return result;
};

// Readable measured profiles; all solid construction is performed by code above.
const SHROUD_PROFILE = [[75.9614788,-0.2978286],[76.111208,-0.4337536],[76.2374898,-0.5917461],[76.3420834,-0.7649173],[76.4297667,-0.9472623],[76.5065223,-1.1344939],[76.578122,-1.3237717],[76.6455382,-1.5145887],[76.706869,-1.707422],[76.7612299,-1.9023381],[76.8113848,-2.0983932],[76.8610652,-2.2945705],[76.9122639,-2.4903435],[76.9644073,-2.685875],[77.0167157,-2.881374],[77.0685832,-3.07698],[77.1194848,-3.2728451],[77.1689746,-3.4690548],[77.2169609,-3.6656511],[77.2634339,-3.8626024],[77.3084239,-4.0599129],[77.3520446,-4.2575257],[77.3944318,-4.4553951],[77.4353843,-4.653576],[77.4745378,-4.8521245],[77.5116762,-5.051058],[77.5473314,-5.2502541],[77.5822768,-5.4495797],[77.6152302,-5.6492337],[77.6410059,-5.8499469],[77.6538352,-6.0518763],[77.6478821,-6.2540867],[77.6180871,-6.454179],[77.4835205,-6.3001133],[77.3640915,-6.1340012],[77.2575175,-5.9593646],[77.1607322,-5.7791102],[77.0702636,-5.5955884],[76.9827353,-5.4106395],[76.8968712,-5.224915],[76.8125142,-5.0385005],[76.7295773,-4.8514552],[76.6484377,-4.6636237],[76.569492,-4.4748533],[76.4933978,-4.2849226],[76.4209724,-4.0935691],[76.3530607,-3.9005479],[76.2902308,-3.7058274],[76.2329079,-3.5094126],[76.181322,-3.3114219],[76.1350842,-3.1121092],[76.0936934,-2.9117351],[76.0557701,-2.7106697],[76.0189929,-2.5093788],[75.9813036,-2.3082648],[75.9433625,-2.1071999],[75.9072204,-1.9058225],[75.8747274,-1.7038095],[75.8470856,-1.5010738],[75.8253166,-1.2976283],[75.812184,-1.0934599],[75.813357,-0.8888743],[75.8350589,-0.6854887],[75.8831734,-0.4867262]];

// Each profile point is [chord fraction, normal ordinate / chord, camber / chord].
